Get-ChildItem -Filter *.html | ForEach-Object { $content = Get-Content $_.FullName -Raw; $newMeta = "<meta name=`"viewport`" content=`"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no`">"; if ($content -notmatch "<meta name=`"viewport`"") { $content = $content -replace "<head>", "<head>`n    $newMeta" } else { $content = $content -replace "<meta name=`"viewport`".*?>", $newMeta }; Set-Content -Path $_.FullName -Value $content -NoNewline }
